function App() {
  const [email, setEmail] = useState("");
  const valid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  return <form onSubmit={e => { e.preventDefault(); alert("Saved: " + email); }}><label>Email <input type="email" value={email} onChange={e => setEmail(e.target.value)} aria-describedby="email-help" /></label><p id="email-help">{email && !valid ? "Enter an address such as name@example.com." : "We will use this address to contact you."}</p><button disabled={!valid}>Create account</button></form>;
}
